// environmental glimmers
const wisps=[];for(let i=0;i<24;i++){const w=new THREE.Mesh(new THREE.SphereGeometry(rand(.035,.075),7,6),new THREE.MeshBasicMaterial({color:i%2?0xeed494:0xa7ebd8,transparent:true,opacity:.75}));w.position.set(rand(-22,22),rand(.4,4),rand(-30,20));w.userData={phase:rand(0,6),baseY:w.position.y};scene.add(w);wisps.push(w)}
const clock=new THREE.Clock(),keys={},effects=[];let active=false,yaw=0,attackTime=0,dashTime=0,burstCD=0,dashCD=0,health=100,xp=0,kills=0,level=1,combo=0,comboTimer=0,invuln=0,toastTimer=0,waystoneUsed=false;
const ui={hp:document.getElementById('hpFill'),hpText:document.getElementById('hpText'),xp:document.getElementById('xpFill'),xpText:document.getElementById('xpText'),count:document.getElementById('count'),progress:document.getElementById('questProgress'),quest:document.getElementById('questTitle'),detail:document.getElementById('questDetail'),toast:document.getElementById('toast'),prompt:document.getElementById('prompt')};
function notify(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=2.4}
function updateBars(){ui.hp.style.width=health+'%';ui.hpText.textContent=Math.ceil(health)+' / 100';ui.xp.style.width=(xp%100)+'%';ui.xpText.textContent=(xp%100)+' / 100';document.getElementById('level').textContent=String(level).padStart(2,'0');ui.count.textContent=kills;ui.progress.style.width=(kills/3*100)+'%';if(kills>=3){ui.quest.textContent='THE SONG RETURNS';ui.detail.innerHTML='The meadow breathes again.<br>Seek the ancient waystone';ui.progress.style.width='100%'}}
function showFlash(){const f=document.getElementById('flash');f.classList.remove('hit');void f.offsetWidth;f.classList.add('hit')}
function effectRing(position,color=0x9df5df){const ring=new THREE.Mesh(new THREE.TorusGeometry(.7,.055,7,32),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));ring.rotation.x=Math.PI/2;ring.position.copy(position);ring.position.y=.12;scene.add(ring);effects.push({object:ring,life:.42,max:.42,type:'ring'});}
function burstParticles(pos,color,count=22){for(let i=0;i<count;i++){const p=new THREE.Mesh(new THREE.IcosahedronGeometry(rand(.035,.12),0),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}));p.position.copy(pos);p.position.y+=rand(.1,1.9);scene.add(p);const a=Math.random()*6.28,s=rand(2,7);effects.push({object:p,life:rand(.35,.8),max:.8,vel:new THREE.Vector3(Math.cos(a)*s,rand(1,6),Math.sin(a)*s)})}}
function damageEnemy(e,damage){if(!e.userData.alive)return;e.userData.hp-=damage;e.userData.hit=.2;burstParticles(e.position.clone().add(new THREE.Vector3(0,1.2,0)),0x91f2dc,7);if(e.userData.hp<=0){e.userData.alive=false;burstParticles(e.position.clone().add(new THREE.Vector3(0,1,0)),0xc3f9e3,30);scene.remove(e);kills++;xp+=35;if(xp>=100){xp-=100;level++;health=Math.min(100,health+25);notify('✧  ADVENTURE LEVEL UP · '+level)}else notify('SHADE DISPELLED  ·  +35 XP');updateBars()}}
function attack(power=1,range=4.2){if(!active||attackTime>0)return;attackTime=.42;combo=(combo%3)+1;comboTimer=1;body.rotation.x=-.13;sword.rotation.z=-.85;effectRing(player.position.clone().add(new THREE.Vector3(0,.15,-1.05)),0xa4f4df);let facing=new THREE.Vector3(Math.sin(yaw),0,-Math.cos(yaw));let hit=false;for(const e of enemies){if(!e.userData.alive)continue;const d=e.position.clone().sub(player.position);const dist=d.length();if(dist<range&&d.normalize().dot(facing)>.05){damageEnemy(e,power);hit=true}}if(hit){xp+=2;updateBars()}}
function galeStep(){if(!active||dashCD>0)return;dashTime=.32;dashCD=2.2;invuln=.45;effectRing(player.position.clone(),0xc0ffe9);notify('GALE STEP');}
function tempest(){if(!active||burstCD>0)return;burstCD=8;burstParticles(player.position.clone(),0x9fffe3,40);effectRing(player.position.clone(),0x9fffe3);for(const e of enemies){if(e.userData.alive&&e.position.distanceTo(player.position)<8)damageEnemy(e,3)}notify('TEMPEST BLOOM');}
function interact(){if(player.position.distanceTo(waystone.position)<4){if(!waystoneUsed){waystoneUsed=true;health=100;updateBars();notify('WAYSTONE ATTUNED  ·  VITALITY RESTORED');crystal.material.emissiveIntensity=3.5}else{health=100;updateBars();notify('VITALITY RESTORED')}}}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='ShiftLeft'||e.code==='ShiftRight')galeStep();if(e.code==='KeyQ')tempest();if(e.code==='KeyF')interact();if(e.code==='Space'||e.code==='Enter')attack()});window.addEventListener('keyup',e=>keys[e.code]=false);
document.getElementById('begin').addEventListener('click',()=>{active=true;const intro=document.getElementById('intro');intro.style.opacity='0';setTimeout(()=>intro.remove(),1000);notify('THE MEADOW AWAITS');});
document.getElementById('skillDash').addEventListener('click',galeStep);document.getElementById('skillBurst').addEventListener('click',tempest);document.getElementById('skillAttack').addEventListener('click',()=>attack());renderer.domElement.addEventListener('click',()=>{if(active)attack()});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());
// Drag to turn the camera, with a gentle keyboard-facing camera follow.
let dragging=false,lastX=0;renderer.domElement.addEventListener('pointerdown',e=>{if(e.button===2){dragging=true;lastX=e.clientX}});window.addEventListener('pointerup',()=>dragging=false);window.addEventListener('pointermove',e=>{if(dragging){yaw-=(e.clientX-lastX)*.006;lastX=e.clientX}});
function coolUI(id,time,max){const el=document.querySelector(id);if(time>0){el.classList.add('cooling');el.querySelector('.cool').textContent=Math.ceil(time*10)/10}else el.classList.remove('cooling')}
function update(dt,t){if(!active)return;attackTime=Math.max(0,attackTime-dt);dashTime=Math.max(0,dashTime-dt);dashCD=Math.max(0,dashCD-dt);burstCD=Math.max(0,burstCD-dt);invuln=Math.max(0,invuln-dt);comboTimer=Math.max(0,comboTimer-dt);if(comboTimer===0)combo=0;coolUI('#skillDash',dashCD,2.2);coolUI('#skillBurst',burstCD,8);
// camera-relative movement
let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);let move=new THREE.Vector3(Math.sin(yaw)*forward+Math.cos(yaw)*side,0,-Math.cos(yaw)*forward+Math.sin(yaw)*side);if(move.lengthSq()>0){move.normalize();const speed=dashTime>0?19:5.7;player.position.addScaledVector(move,speed*dt);player.rotation.y=Math.atan2(move.x,-move.z);body.rotation.x=attackTime>0?-.18:Math.sin(t*11)*.035;legL.rotation.x=Math.sin(t*10)*.46*(dashTime>0?0:1);legR.rotation.x=-Math.sin(t*10)*.46*(dashTime>0?0:1);armL.rotation.x=Math.sin(t*10)*.23;armR.rotation.x=attackTime>0?-.4:Math.sin(t*10)*.18}else{body.rotation.x=attackTime>0?-.15:Math.sin(t*1.7)*.018;legL.rotation.x*=.8;legR.rotation.x*=.8;armL.rotation.x*=.85;armR.rotation.x*=.85}
if(dashTime>0){const d=new THREE.Vector3(Math.sin(player.rotation.y),0,-Math.cos(player.rotation.y));player.position.addScaledVector(d,8*dt)}if(attackTime<=0)sword.rotation.z=.25;player.position.x=THREE.MathUtils.clamp(player.position.x,-63,63);player.position.z=THREE.MathUtils.clamp(player.position.z,-49,55);
// smooth chase camera
const target=new THREE.Vector3(player.position.x+Math.sin(yaw)*8,player.position.y+5.4,player.position.z+Math.cos(yaw)*8);camera.position.lerp(target,1-Math.exp(-4*dt));camera.lookAt(player.position.x,player.position.y+1.55,player.position.z);
// waystone and follower motes
crystal.rotation.y=t*.8;crystal.position.y=1.65+Math.sin(t*1.4)*.12;ring.rotation.z=t*.4;waystone.children.forEach((o,i)=>{if(o.isMesh&&o!==pedestal){o.rotation.y+=dt*.15}});player.children.filter(o=>o.isMesh&&o.geometry.type==='SphereGeometry').forEach((m,i)=>{const a=t*1.1+m.userData.phase;m.position.set(Math.cos(a)*.75,1.5+Math.sin(a*1.3)*.65,Math.sin(a)*.65)});
for(const w of wisps){w.position.y=w.userData.baseY+Math.sin(t*1.2+w.userData.phase)*.45;w.position.x+=Math.sin(t*.3+w.userData.phase)*dt*.12}
// foes drift, stalk, and strike
for(const e of enemies){if(!e.userData.alive)continue;const u=e.userData;u.phase+=dt;u.attack=Math.max(0,u.attack-dt);e.position.y=.12+Math.sin(u.phase*2.2)*.12;e.rotation.y+=dt*.35;e.children[1].scale.setScalar(1+Math.sin(u.phase*3)*.08);if(u.hit>0){u.hit-=dt;e.scale.setScalar(1.13)}else e.scale.lerp(new THREE.Vector3(1,1,1),.2);const delta=player.position.clone().sub(e.position);const dist=delta.length();if(dist>2.2&&dist<17){delta.y=0;delta.normalize();e.position.addScaledVector(delta,dt*(dist>5?1.3:.55));e.rotation.y=Math.atan2(delta.x,delta.z)}else if(dist<2.6&&u.attack<=0&&invuln<=0){u.attack=1.55;health=Math.max(0,health-9);updateBars();showFlash();if(health<=0){health=60;player.position.set(0,0,9);notify('THE WAYSTONE RETURNS YOU TO THE MEADOW');updateBars()}}}
let near=player.position.distanceTo(waystone.position)<4;ui.prompt.classList.toggle('show',near);for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;if(e.type==='ring'){e.object.scale.setScalar(1+(1-e.life/e.max)*3);e.object.material.opacity=Math.max(0,e.life/e.max)}else{e.object.position.addScaledVector(e.vel,dt);e.vel.y-=7*dt;e.object.material.opacity=Math.max(0,e.life/e.max)}if(e.life<=0){scene.remove(e.object);effects.splice(i,1)}}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}}
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.04),t=clock.elapsedTime;update(dt,t);renderer.render(scene,camera)}frame();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
</script>
</body>
</html>

